);
export type ButtonProps = ComponentPropsWithoutRef<typeof ark.button> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
    href?: string;
    icon?: ReactNode;
    iconLeft?: ReactNode;
    iconRight?: ReactNode;
    label?: ReactNode;
    loading?: boolean;
    loadingText?: string;
  };
export function Button({
  className,
  theme,
  variant,
  size,
  asChild = false,
  href,
  icon,
  iconLeft,
  iconRight,
  label,
  loading = false,
  loadingText,
  disabled,
  type = "button",
  children,
  ...props
}: ButtonProps) {
  const content = (
    <>
      {loading ? (
        <svg
          className="size-4 animate-spin"
          viewBox="0 0 24 24"
          fill="none"
          aria-hidden="true"
        >
          <circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="3" className="opacity-25" />
          <path d="M21 12a9 9 0 0 0-9-9" stroke="currentColor" strokeWidth="3" strokeLinecap="round" />
        </svg>
      ) : (
        iconLeft ?? icon
      )}
      {loading && loadingText ? loadingText : (children ?? label)}
      {!loading && iconRight}
    </>
  );

  const classes = cn(buttonVariants({ theme, variant, size }), className);

  if (href && !disabled) {
    return (
      <ark.a
        href={href}
        target="_blank"
        rel="noreferrer noopener"
        className={classes}
        aria-busy={loading || undefined}
        {...props}
      >
        {content}
      </ark.a>
    );
  }

  return (
    <ark.button
      asChild={asChild}
      type={type}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      aria-label={label ? String(label) : undefined}
      className={classes}
      {...props}
    >
      {content}
    </ark.button>
  );
}

